template <typename UnionPtrType>
TextQueryResponsePtr TextQueryResponse::Clone() const {
  switch (tag_) {
    case Tag::kResults:
      return NewResults(
          mojo::Clone(*data_.results));
    case Tag::kError:
      return NewError(
          mojo::Clone(*data_.error));
  }
  return nullptr;
}

template <typename T,
          typename std::enable_if<std::is_same<
              T, TextQueryResponse>::value>::type*>
bool TextQueryResponse::Equals(const T& other) const {
  if (tag_ != other.which())
    return false;

  switch (tag_) {
    case Tag::kResults:
      return mojo::Equals(*(data_.results), *(other.data_.results));
    case Tag::kError:
      return mojo::Equals(*(data_.error), *(other.data_.error));
  }

  return false;
}
